/**
 * Register this plugin's own Remote namespace with the Typert registry.
 *
 * A `ctx.remote.<namespace>` namespace normally comes from a `./typert`
 * artifact generated by `@deepseek-ai/dsh-typert-generator`; a hand-written
 * plugin has no way to run that generator, and `dsh-typert-loader` skips any
 * package without the export. The loader's own documentation names the escape
 * hatch for exactly this case: "Manual `ctx.typert.register()` remains
 * available for contributions that do not use a `./typert` artifact
 * (hand-written wire schemas, tests, non-loader compositions)".
 *
 * The registry's own package (`@deepseek-ai/dsh-typert-registry`) is not
 * resolvable from a profile-installed plugin, and the `typert` service type
 * this composition does expose describes only the read side. Both the service
 * and its contribution are therefore taken structurally and validated at call
 * time, which is honest about what is and is not checked at compile time.
 *
 * The codec is declared `src-json`: the source-level JSON shape is trusted
 * instead of being validated against a generated runtime schema, which keeps
 * this module free of a zod dependency.
 *
 * @module commandcode-plans-provider/typert
 */

import type { Context } from '@deepseek-ai/cordis'
import type { InvocationDescriptor } from '@deepseek-ai/dsh-typert-protocol'

/** Package name this contribution is attributed to. */
export const TYPERT_PACKAGE = '@local/commandcode-plans-provider'

/** Cordis service key that owns the exported method; also the wire namespace. */
export const TYPERT_SERVICE = 'commandcodeUsage'

/**
 * Hand-written strict codecs.
 *
 * The client assembly refuses a descriptor whose field carries no strict codec,
 * so `src-json` is not usable even though the protocol declares it. A
 * `TypertSchema` only has to answer `parse`, which is what keeps this free of a
 * zod dependency.
 */
const BOOLEAN_SCHEMA = {
  parse(value: unknown): boolean {
    if (typeof value !== 'boolean') throw new Error('expected a boolean')
    return value
  },
}

const JSON_SCHEMA = {
  parse(value: unknown): unknown {
    return value
  },
}

/** Strict codec for the `force` parameter. */
const FORCE_CODEC = {
  mode: 'strict' as const,
  typeSymbol: `${TYPERT_PACKAGE}#${TYPERT_SERVICE}/snapshot:force`,
  create: () => BOOLEAN_SCHEMA,
}

/** Strict codec for the snapshot result. */
const RESULT_CODEC = {
  mode: 'strict' as const,
  typeSymbol: `${TYPERT_PACKAGE}#${TYPERT_SERVICE}/snapshot:result`,
  create: () => JSON_SCHEMA,
}

/** The register entry point, as the loader documents it. */
interface TypertRegistrar {
  register(contribution: unknown): unknown
}

/**
 * The one exported invocation: `commandcodeUsage/snapshot`.
 *
 * `force` is required rather than optional because an omitted wire field would
 * have to decode to `undefined`, which needs an explicit
 * `acceptsUndefined: true` declaration — the page always knows whether it wants
 * a cached or a fresh read, so it always sends one.
 * @returns the invocation descriptor.
 */
function snapshotInvocation(): InvocationDescriptor {
  return {
    id: `${TYPERT_PACKAGE}#${TYPERT_SERVICE}/snapshot`,
    service: TYPERT_SERVICE,
    namespace: TYPERT_SERVICE,
    method: 'snapshot',
    invocation: { kind: 'direct' },
    parameters: [
      {
        name: 'force',
        wire: 'force',
        source: 'json',
        codec: FORCE_CODEC,
      },
    ],
    result: RESULT_CODEC,
    sourceLocation: { file: 'src/remote.ts', line: 46, column: 3 },
  }
}

/**
 * Resolve the Typert registrar from a context, if this composition mounts one.
 * @param ctx - the plugin's cordis context.
 * @returns the registrar, or `undefined` when no registry is mounted.
 */
function registrarOf(ctx: Context): TypertRegistrar | undefined {
  const registry = (ctx as unknown as { get(name: string): unknown }).get('typert')
  if (registry === null || registry === undefined) return undefined
  const register = (registry as { register?: unknown }).register
  return typeof register === 'function' ? registry as TypertRegistrar : undefined
}

/**
 * Register the usage namespace so the browser can read it.
 *
 * The Typert service is optional: a composition without the registry keeps
 * working, and the dock cell reports an unavailable read instead of the plugin
 * failing to activate.
 * @param ctx - the plugin's cordis context.
 * @param log - warn sink used when the registry is absent or refuses.
 * @returns whether the namespace was registered.
 */
export function registerUsageNamespace(ctx: Context, log: (message: string) => void): boolean {
  const registrar = registrarOf(ctx)
  if (registrar === undefined) {
    log('no typert registry is mounted; the usage ring will report an unavailable read')
    return false
  }
  try {
    registrar.register({
      package: TYPERT_PACKAGE,
      face: 'host',
      schemas: [],
      invocations: [snapshotInvocation()],
      model: {
        services: [
          {
            key: TYPERT_SERVICE,
            exportName: 'CommandCodeUsageController',
            summary: 'Host half of the browser usage read for a Command Code subscription.',
            description:
              'Serves the subscription usage snapshot over one Remote namespace so the composer-dock '
              + 'cell can render the 5-hour window without reading the billing endpoint itself.',
            tags: [],
            members: [
              {
                kind: 'method',
                name: 'snapshot',
                signature: '@Remote async snapshot(force: boolean): Promise<UsageSnapshot>',
                summary: 'Latest usage snapshot for the account.',
              },
            ],
            types: [
              {
                name: 'UsageSnapshot',
                declaration:
                  'export interface UsageSnapshot { ok: boolean; error?: string; fetchedAt: string;'
                  + ' fiveHour?: WindowUsage; weekly?: WindowUsage; planId?: string; limited?: boolean;'
                  + ' exceeded?: boolean }',
              },
            ],
          },
        ],
        events: [],
        objects: [],
      },
    })
    return true
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error)
    log(`the typert registry refused the usage namespace: ${message}`)
    return false
  }
}
